import api
def run(name="Frodo Baggins", suffix=", retired"):
    r=api.searchEmployees(name=name)
    assert r['status']==200
    items=r['body']['items']
    if len(items)!=1: raise Exception(f"expected 1 match, got {len(items)}")
    id=items[0]['id']
    g=api.getEmployee(id)
    if g['status']!=200: raise Exception(g)
    b=g['body']
    if b['status'] not in ('working','on notice'): raise Exception("not updatable")
    u=api.update(id,{"firstName":b['firstName'],"lastName":b['lastName'],"role":b['role']+suffix},if_match=g['etag'])
    if u['status']!=200: raise Exception(u)
    return u['body']
print(run())
